      --cream: #FEFAE0;
      --cream-dark: #FAF3C0;
      --text: #1a1a1a;
      --text-muted: #5a6a5f;
      --white: #ffffff;
      --shadow-sm: 0 2px 8px rgba(45,106,79,0.10);
      --shadow-md: 0 6px 24px rgba(45,106,79,0.13);
      --shadow-lg: 0 16px 48px rgba(45,106,79,0.16);
      --radius: 20px;
      --radius-sm: 12px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', sans-serif;
      background: var(--cream);
      color: var(--text);
      line-height: 1.6;
      overflow-x: hidden;
    }

    h1, h2, h3, h4, h5 {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      line-height: 1.2;
    }

    /* ───────── HEADER ───────── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254, 250, 224, 0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(45,106,79,0.12);
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      flex-shrink: 0;
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
    }

    .logo-text {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 20px;
      color: var(--green-dark);
      letter-spacing: -0.3px;
    }

    .logo-text span { color: var(--orange); }

    .nav {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .nav a {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 15px;
      color: var(--text-muted);
      text-decoration: none;
      padding: 8px 16px;
      border-radius: 10px;
      transition: color 0.2s, background 0.2s;
    }

    .nav a:hover {
      color: var(--green);
      background: var(--green-muted);
    }

    .header-cta {
      background: var(--green);
      color: var(--white) !important;
      border-radius: 10px;
      padding: 10px 20px !important;
      transition: background 0.2s, transform 0.15s !important;
    }

    .header-cta:hover {
      background: var(--green-dark) !important;
      transform: translateY(-1px);
    }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      cursor: pointer;
      padding: 6px;
      border: none;
      background: none;
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--green);
      border-radius: 2px;
      transition: transform 0.3s;
    }

    /* ───────── HERO ───────── */
    .hero {
      background: linear-gradient(135deg, #1B4332 0%, #2D6A4F 50%, #40916C 100%);
      position: relative;
      overflow: hidden;
      min-height: 580px;
      display: flex;
      align-items: center;
    }

    .hero-bg-pattern {
      position: absolute;
      inset: 0;
      background-image:
        radial-gradient(circle at 20% 50%, rgba(244,162,97,0.15) 0%, transparent 50%),
        radial-gradient(circle at 80% 20%, rgba(82,183,136,0.2) 0%, transparent 40%),
        radial-gradient(circle at 60% 80%, rgba(254,250,224,0.08) 0%, transparent 30%);
    }

    .hero-dots {
      position: absolute;
      inset: 0;
      background-image: radial-gradient(circle, rgba(255,255,255,0.06) 1px, transparent 1px);
      background-size: 28px 28px;
    }

    .hero-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 80px 24px;
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      align-items: center;
      gap: 60px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(244,162,97,0.2);
      border: 1px solid rgba(244,162,97,0.4);
      color: var(--orange);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 13px;
      padding: 6px 14px;
      border-radius: 100px;
      margin-bottom: 20px;
      letter-spacing: 0.5px;
    }

    .hero-badge::before { content: '✦'; font-size: 10px; }

    .hero-title {
      font-size: clamp(36px, 5vw, 60px);
      font-weight: 900;
      color: var(--white);
      letter-spacing: -1px;
      margin-bottom: 20px;
      line-height: 1.1;
    }

    .hero-title .accent { color: var(--orange); }

    .hero-subtitle {
      font-size: 17px;
      color: rgba(255,255,255,0.80);
      line-height: 1.7;
      margin-bottom: 36px;
      max-width: 480px;
    }

    .hero-actions {
      display: flex;
      gap: 14px;
      flex-wrap: wrap;
    }

    .btn-primary {
      background: var(--orange);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 15px;
      padding: 14px 28px;
      border-radius: 14px;
      border: none;
      cursor: pointer;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
      box-shadow: 0 4px 14px rgba(244,162,97,0.4);
    }

    .btn-primary:hover {
      background: var(--orange-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(244,162,97,0.5);
    }

    .btn-secondary {
      background: rgba(255,255,255,0.12);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 15px;
      padding: 14px 28px;
      border-radius: 14px;
      border: 1px solid rgba(255,255,255,0.25);
      cursor: pointer;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      transition: background 0.2s, border-color 0.2s, transform 0.15s;
      backdrop-filter: blur(4px);
    }

    .btn-secondary:hover {
      background: rgba(255,255,255,0.20);
      border-color: rgba(255,255,255,0.40);
      transform: translateY(-2px);
    }

    .hero-visual {
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .hero-food-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      max-width: 360px;
    }

    .hero-food-cell {
      aspect-ratio: 1;
      border-radius: 18px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 42px;
      box-shadow: var(--shadow-md);
      transition: transform 0.3s;
      animation: floatCell 3s ease-in-out infinite;
    }

    .hero-food-cell:nth-child(2) { animation-delay: 0.3s; }
    .hero-food-cell:nth-child(3) { animation-delay: 0.6s; }
    .hero-food-cell:nth-child(4) { animation-delay: 0.9s; }
    .hero-food-cell:nth-child(5) { animation-delay: 1.2s; }
    .hero-food-cell:nth-child(6) { animation-delay: 1.5s; }
    .hero-food-cell:nth-child(7) { animation-delay: 1.8s; }
    .hero-food-cell:nth-child(8) { animation-delay: 2.1s; }
    .hero-food-cell:nth-child(9) { animation-delay: 2.4s; }

    @keyframes floatCell {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-6px); }
    }

    /* ───────── SECTION COMMON ───────── */
    .section {
      padding: 80px 0;
    }

    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .section-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 12px;
      letter-spacing: 2px;
      text-transform: uppercase;
      color: var(--green);
      margin-bottom: 10px;
    }

    .section-title {
      font-size: clamp(26px, 3.5vw, 40px);
      color: var(--green-dark);
      margin-bottom: 12px;
    }

    .section-subtitle {
      font-size: 16px;
      color: var(--text-muted);
      max-width: 560px;
      line-height: 1.7;
    }

    .section-header {
      margin-bottom: 48px;
    }

    /* ───────── FEATURED PRODUCTS ───────── */
    .featured-section {
      background: var(--white);
    }

    .carousel-wrapper {
      position: relative;
    }

    .carousel-track-outer {
      overflow: hidden;
      border-radius: var(--radius);
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      will-change: transform;
    }

    .product-card {
      flex: 0 0 calc(25% - 15px);
      background: var(--cream);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform 0.3s, box-shadow 0.3s;
      border: 1px solid rgba(45,106,79,0.08);
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-md);
    }

    .product-img {
      width: 100%;
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 64px;
      position: relative;
      overflow: hidden;
    }

    .product-img-badge {
      position: absolute;
      top: 12px;
      right: 12px;
      background: var(--green);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 11px;
      padding: 4px 10px;
      border-radius: 100px;
    }

    .product-body {
      padding: 18px 20px 20px;
    }

    .product-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 16px;
      color: var(--green-dark);
      margin-bottom: 6px;
      line-height: 1.3;
    }

    .product-desc {
      font-size: 13px;
      color: var(--text-muted);
      line-height: 1.5;
      margin-bottom: 14px;
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .product-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 20px;
      color: var(--green);
    }

    .add-btn {
      background: var(--orange);
      color: var(--white);
      border: none;
      border-radius: 10px;
      width: 36px;
      height: 36px;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      font-size: 20px;
      font-weight: 700;
      transition: background 0.2s, transform 0.15s;
      line-height: 1;
    }

    .add-btn:hover {
      background: var(--orange-dark);
      transform: scale(1.1);
    }

    .carousel-controls {
      display: flex;
      justify-content: center;
      align-items: center;
      gap: 16px;
      margin-top: 32px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 2px solid var(--green);
      background: var(--white);
      color: var(--green);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      transition: background 0.2s, color 0.2s, transform 0.15s;
      box-shadow: var(--shadow-sm);
    }

    .carousel-btn:hover {
      background: var(--green);
      color: var(--white);
      transform: scale(1.1);
    }

    .carousel-btn:disabled {
      opacity: 0.35;
      cursor: not-allowed;
      transform: none;
    }

    .carousel-dots {
      display: flex;
      gap: 8px;
      align-items: center;
    }

    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--green-muted);
      cursor: pointer;
      transition: background 0.2s, transform 0.2s;
      border: none;
    }

    .carousel-dot.active {
      background: var(--green);
      transform: scale(1.3);
    }

    /* ───────── BRAND HIGHLIGHTS ───────── */
    .highlights-section {
      background: linear-gradient(135deg, var(--green-dark), var(--green));
      padding: 60px 0;
    }

    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2px;
    }

    .highlight-item {
      padding: 32px 24px;
      text-align: center;
      position: relative;
    }

    .highlight-item + .highlight-item::before {
      content: '';
      position: absolute;
      left: 0;
      top: 20%;
      height: 60%;
      width: 1px;
      background: rgba(255,255,255,0.15);
    }

    .highlight-number {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: clamp(36px, 4vw, 52px);
      color: var(--orange);
      line-height: 1;
      margin-bottom: 8px;
      letter-spacing: -1px;
    }

    .highlight-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 15px;
      color: rgba(255,255,255,0.90);
      margin-bottom: 6px;
    }

    .highlight-sub {
      font-size: 13px;
      color: rgba(255,255,255,0.55);
      line-height: 1.4;
    }

    /* ───────── SEASONAL PICKS ───────── */
    .seasonal-section {
      background: var(--cream);
    }

    .seasonal-header-row {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 40px;
      flex-wrap: wrap;
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      border: 1px solid rgba(45,106,79,0.08);
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .seasonal-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-md);
    }

    .seasonal-img {
      width: 100%;
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 56px;
      position: relative;
    }

    .seasonal-tag {
      position: absolute;
      top: 12px;
      left: 12px;
      background: var(--orange);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 11px;
      padding: 4px 10px;
      border-radius: 100px;
    }

    .seasonal-body {
      padding: 18px 20px 20px;
    }

    .seasonal-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 15px;
      color: var(--green-dark);
      margin-bottom: 6px;
      line-height: 1.3;
    }

    .seasonal-desc {
      font-size: 13px;
      color: var(--text-muted);
      line-height: 1.5;
      margin-bottom: 14px;
    }

    .seasonal-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 18px;
      color: var(--green);
    }

    /* ───────── CATEGORIES ───────── */
    .categories-section {
      background: var(--white);
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 20px;
    }

    .category-card {
      border-radius: var(--radius);
      overflow: hidden;
      cursor: pointer;
      position: relative;
      aspect-ratio: 3/4;
      transition: transform 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94), box-shadow 0.35s;
      box-shadow: var(--shadow-sm);
    }

    .category-card:hover {
      transform: scale(1.04);
      box-shadow: var(--shadow-lg);
      z-index: 2;
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      font-size: 56px;
      padding: 20px 16px;
      text-align: center;
      position: relative;
      transition: filter 0.35s;
    }

    .category-card:hover .category-bg {
      filter: brightness(0.85);
    }

    .category-emoji-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 14px;
      margin-top: 12px;
      line-height: 1.3;
      transition: opacity 0.25s;
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(27,67,50,0.88) 0%, rgba(27,67,50,0.40) 50%, transparent 100%);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-end;
      padding: 20px 16px;
      opacity: 0;
      transition: opacity 0.35s;
    }

    .category-card:hover .category-overlay {
      opacity: 1;
    }

    .category-overlay-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 16px;
      color: var(--white);
      text-align: center;
      line-height: 1.3;
      transform: translateY(8px);
      transition: transform 0.35s;
    }

    .category-card:hover .category-overlay-name {
      transform: translateY(0);
    }

    .category-overlay-sub {
      font-size: 12px;
      color: rgba(255,255,255,0.75);
      text-align: center;
      margin-top: 4px;
      line-height: 1.4;
      transform: translateY(8px);
      transition: transform 0.35s 0.05s;
    }

    .category-card:hover .category-overlay-sub {
      transform: translateY(0);
    }

    /* ───────── STORE LOCATOR ───────── */
    .locator-section {
      background: linear-gradient(180deg, var(--cream) 0%, #EAF4ED 100%);
    }

    .locator-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: start;
    }

    .locator-form-wrap {
      background: var(--white);
      border-radius: var(--radius);
      padding: 40px;
      box-shadow: var(--shadow-md);
    }

    .locator-form-title {
      font-size: 28px;
      color: var(--green-dark);
      margin-bottom: 8px;
    }

    .locator-form-sub {
      font-size: 15px;
      color: var(--text-muted);
      line-height: 1.6;
      margin-bottom: 28px;
    }

    .zip-input-row {
      display: flex;
      gap: 12px;
    }

    .zip-input {
      flex: 1;
      padding: 14px 18px;
      border: 2px solid var(--green-muted);
      border-radius: var(--radius-sm);
      font-family: 'Plus Jakarta Sans', sans-serif;
      font-size: 15px;
      color: var(--text);
      background: var(--cream);
      outline: none;
      transition: border-color 0.2s;
    }

    .zip-input:focus { border-color: var(--green); }
    .zip-input::placeholder { color: #aab8b0; }

    .search-btn {
      background: var(--green);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 15px;
      padding: 14px 24px;
      border-radius: var(--radius-sm);
      border: none;
      cursor: pointer;
      white-space: nowrap;
      transition: background 0.2s, transform 0.15s;
    }

    .search-btn:hover {
      background: var(--green-dark);
      transform: translateY(-1px);
    }

    .store-results {
      margin-top: 24px;
      display: none;
    }

    .store-results.visible { display: block; }

    .store-result-item {
      background: var(--cream);
      border-radius: var(--radius-sm);
      padding: 18px 20px;
      margin-bottom: 12px;
      border: 1px solid rgba(45,106,79,0.10);
      display: flex;
      align-items: flex-start;
      gap: 16px;
      transition: box-shadow 0.2s;
      animation: slideIn 0.35s ease both;
    }

    .store-result-item:hover { box-shadow: var(--shadow-sm); }

    @keyframes slideIn {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .store-result-item:nth-child(2) { animation-delay: 0.07s; }
    .store-result-item:nth-child(3) { animation-delay: 0.14s; }

    .store-icon {
      width: 44px;
      height: 44px;
      background: var(--green-muted);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 22px;
      flex-shrink: 0;
    }

    .store-info { flex: 1; }

    .store-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 15px;
      color: var(--green-dark);
      margin-bottom: 3px;
    }

    .store-address {
      font-size: 13px;
      color: var(--text-muted);
      margin-bottom: 4px;
    }

    .store-hours {
      font-size: 12px;
      color: var(--green);
      font-weight: 600;
    }

    .store-distance {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 14px;
      color: var(--orange);
      white-space: nowrap;
    }

    .locator-map-side {
      position: sticky;
      top: 96px;
    }

    .map-placeholder {
      background: var(--green-muted);
      border-radius: var(--radius);
      aspect-ratio: 4/3;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 16px;
      box-shadow: var(--shadow-md);
      position: relative;
      overflow: hidden;
    }

    .map-grid {
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(45,106,79,0.12) 1px, transparent 1px),
        linear-gradient(90deg, rgba(45,106,79,0.12) 1px, transparent 1px);
      background-size: 32px 32px;
    }

    .map-pin {
      width: 64px;
      height: 64px;
      background: var(--green);
      border-radius: 50% 50% 50% 0;
      transform: rotate(-45deg);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      position: relative;
      z-index: 1;
    }

    .map-pin::after {
      content: '🏪';
      transform: rotate(45deg);
      font-size: 24px;
    }

    .map-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 16px;
      color: var(--green-dark);
      position: relative;
      z-index: 1;
    }

    /* ───────── NEWSLETTER ───────── */
    .newsletter-section {
      background: var(--cream);
      padding: 80px 0;
    }

    .newsletter-card {
      background: linear-gradient(135deg, var(--orange) 0%, #E76F51 100%);
      border-radius: 32px;
      padding: 64px 48px;
      text-align: center;
      position: relative;
      overflow: hidden;
      box-shadow: var(--shadow-lg);
    }

    .newsletter-card::before {
      content: '';
      position: absolute;
      top: -60px;
      right: -60px;
      width: 240px;
      height: 240px;
      background: rgba(255,255,255,0.08);
      border-radius: 50%;
    }

    .newsletter-card::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -40px;
      width: 280px;
      height: 280px;
      background: rgba(255,255,255,0.06);
      border-radius: 50%;
    }

    .newsletter-title {
      font-size: clamp(28px, 4vw, 44px);
      color: var(--white);
      margin-bottom: 12px;
      position: relative;
      z-index: 1;
    }

    .newsletter-sub {
      font-size: 16px;
      color: rgba(255,255,255,0.85);
      margin-bottom: 36px;
      max-width: 500px;
      margin-left: auto;
      margin-right: auto;
      line-height: 1.6;
      position: relative;
      z-index: 1;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 0 auto;
      position: relative;
      z-index: 1;
      flex-wrap: wrap;
      justify-content: center;
    }

    .email-input {
      flex: 1;
      min-width: 220px;
      padding: 14px 20px;
      border: none;
      border-radius: var(--radius-sm);
      font-family: 'Plus Jakarta Sans', sans-serif;
      font-size: 15px;
      background: var(--white);
      color: var(--text);
      outline: none;
      box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    }

    .email-input::placeholder { color: #aaa; }

    .subscribe-btn {
      background: var(--green-dark);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 15px;
      padding: 14px 28px;
      border-radius: var(--radius-sm);
      border: none;
      cursor: pointer;
      transition: background 0.2s, transform 0.15s;
    }

    .subscribe-btn:hover {
      background: var(--green);
      transform: translateY(-1px);
    }

    .newsletter-confirm {
      display: none;
      margin-top: 20px;
      background: rgba(255,255,255,0.20);
      border: 1px solid rgba(255,255,255,0.35);
      border-radius: 12px;
      padding: 14px 24px;
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 15px;
      position: relative;
      z-index: 1;
      animation: fadeIn 0.4s ease;
    }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(4px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .newsletter-confirm.visible { display: block; }

    /* ───────── FOOTER ───────── */
    .footer {
      background: var(--green-dark);
      color: rgba(255,255,255,0.75);
    }

    .footer-top {
      max-width: 1200px;
      margin: 0 auto;
      padding: 64px 24px 40px;
      display: grid;
      grid-template-columns: 1.6fr 1fr 1fr 1fr;
      gap: 48px;
    }

    .footer-brand .logo-text { color: var(--white); }
    .footer-brand .logo-text span { color: var(--orange); }

    .footer-tagline {
      font-size: 14px;
      line-height: 1.7;
      margin-top: 12px;
      color: rgba(255,255,255,0.60);
    }

    .footer-socials {
      display: flex;
      gap: 10px;
      margin-top: 20px;
    }

    .social-btn {
      width: 38px;
      height: 38px;
      border-radius: 10px;
      background: rgba(255,255,255,0.10);
      border: 1px solid rgba(255,255,255,0.15);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 17px;
      text-decoration: none;
      cursor: pointer;
      transition: background 0.2s, transform 0.15s;
    }

    .social-btn:hover {
      background: var(--orange);
      transform: translateY(-2px);
    }

    .footer-col-title {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 14px;
      color: var(--white);
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: 16px;
    }

    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-links a {
      color: rgba(255,255,255,0.60);
      text-decoration: none;
      font-size: 14px;
      transition: color 0.2s;
    }

    .footer-links a:hover { color: var(--orange); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.10);
      padding: 20px 24px;
      text-align: center;
      font-size: 13px;
      color: rgba(255,255,255,0.40);
    }

    /* ───────── MOBILE ───────── */
    @media (max-width: 1100px) {
      .categories-grid { grid-template-columns: repeat(3, 1fr); }
      .seasonal-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-top { grid-template-columns: 1fr 1fr; gap: 32px; }
    }

    @media (max-width: 900px) {
      .hero-inner { grid-template-columns: 1fr; gap: 40px; }
      .hero-visual { order: -1; }
      .hero-food-grid { max-width: 280px; }
      .locator-layout { grid-template-columns: 1fr; }
      .locator-map-side { display: none; }
      .highlights-grid { grid-template-columns: repeat(2, 1fr); }
      .highlight-item + .highlight-item::before { display: none; }
      .product-card { flex: 0 0 calc(50% - 10px); }
    }

    @media (max-width: 768px) {
      .nav { display: none; }
      .hamburger { display: flex; }
      .section { padding: 56px 0; }
      .hero { min-height: auto; }
      .hero-inner { padding: 60px 24px; }
      .hero-food-grid { display: none; }
      .seasonal-grid { grid-template-columns: 1fr 1fr; }
      .categories-grid { grid-template-columns: repeat(2, 1fr); }
      .newsletter-card { padding: 40px 24px; }
      .footer-top { grid-template-columns: 1fr 1fr; padding: 40px 24px; gap: 28px; }
    }

    @media (max-width: 520px) {
      .product-card { flex: 0 0 calc(80% - 10px); }
      .seasonal-grid { grid-template-columns: 1fr; }
      .categories-grid { grid-template-columns: repeat(2, 1fr); }
      .zip-input-row { flex-direction: column; }
      .footer-top { grid-template-columns: 1fr; }
      .highlights-grid { grid-template-columns: 1fr 1fr; }
    }

    /* ───────── SCROLL ANIMATIONS ───────── */
    .reveal {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.6s ease, transform 0.6s ease;
    }

    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    .reveal-delay-1 { transition-delay: 0.1s; }
    .reveal-delay-2 { transition-delay: 0.2s; }
    .reveal-delay-3 { transition-delay: 0.3s; }
    .reveal-delay-4 { transition-delay: 0.4s; }
  </style>
</head>
